#include <cmath>
#include <iomanip>
#include <iostream>
#include <random>

struct Stats {  // Welford's running mean and variance
    long n = 0;
    double mean = 0.0;
    double m2 = 0.0;  // the sum of squared distances from the mean

    void add(double x) {
        ++n;
        const double d = x - mean;  // distance from the old mean
        mean += d / n;
        m2 += d * (x - mean);       // times the distance from the new mean
    }
    double variance() const { return n > 1 ? m2 / (n - 1) : 0.0; }
    double stdev() const { return std::sqrt(variance()); }
    double se() const { return std::sqrt(variance() / n); }  // standard error of the mean
};

int main() {
    const long n = 1000000;
    std::mt19937_64 rng(42);
    double sum = 0.0;
    double sum_sq = 0.0;
    Stats stats;
    for (long i = 0; i < n; ++i) {
        // A quiet market: the mid sits near 19275 and moves by cents.
        double mid = 19275.0 + 0.01 * (static_cast<int>(rng() % 5) - 2);
        sum += mid;
        sum_sq += mid * mid;
        stats.add(mid);
    }
    double naive = (sum_sq - sum * sum / n) / (n - 1);

    std::cout << std::fixed << std::setprecision(8);
    std::cout << "count:            " << stats.n << '\n';
    std::cout << "mean:             " << stats.mean << '\n';
    std::cout << "naive variance:   " << naive << '\n';
    std::cout << "Welford variance: " << stats.variance() << '\n';
    std::cout << "naive stdev:      " << std::sqrt(naive) << '\n';
    std::cout << "Welford stdev:    " << stats.stdev() << '\n';
    std::cout << "standard error:   " << stats.se() << '\n';
    return 0;
}

