steps.body:
A window forgets abruptly: a tick counts fully for N ticks, then not at all. An **exponentially weighted moving average** (EWMA) forgets gradually. Each value pulls the mean a fraction `alpha` of the way toward itself, so an older value's weight shrinks by `1 - alpha` every tick. It needs no buffer, only the mean and a variance:

```cpp harness
#include <iostream>

double alpha_ = 0.2;
double mean_ = 100.0;
double var_ = 0.0;

int main() {
    for (double x : {100.10, 100.05, 100.20}) {
        {{code}}
    }
    std::cout << mean_ << ' ' << var_ << '\n';
    return 0;
}
```

```cpp
double delta = x - mean_;
mean_ += alpha_ * delta;
var_ = (1.0 - alpha_) * (var_ + alpha_ * delta * delta);
```

Pick `alpha` from a *span* N, `2.0 / (N + 1)`, which weighs roughly the last N ticks, or from a *half-life* h, `1 - std::pow(0.5, 1.0 / h)`, after which a tick counts half. Ticks arrive unevenly, so production code often decays by time instead, with `alpha = 1 - std::exp(-dt / tau)` for a gap `dt`.

A **z-score** says how unusual a value is in standard deviations: `(x - mean) / sd`. A mean-reversion signal sells when the price sits more than 2 standard deviations above its EWMA and buys when it's 2 below. Score the new price *before* adding it, or it pulls the mean toward itself and shrinks its own score.

example.code:
#include <cmath>
#include <iomanip>
#include <iostream>

class Ewma {
public:
    explicit Ewma(double alpha) : alpha_(alpha) {}
    void add(double x) {
        if (count_++ == 0) {  // the first value seeds the mean
            mean_ = x;
            return;
        }
        double delta = x - mean_;
        mean_ += alpha_ * delta;
        var_ = (1.0 - alpha_) * (var_ + alpha_ * delta * delta);
    }
    long count() const { return count_; }
    double mean() const { return mean_; }
    double variance() const { return var_; }
    double stdev() const { return std::sqrt(var_); }

private:
    double alpha_;
    long count_ = 0;
    double mean_ = 0.0;
    double var_ = 0.0;
};

// How many standard deviations x sits from the mean, 0 while there is no spread.
double zscore(double x, double mean, double sd) {
    return sd > 0.0 ? (x - mean) / sd : 0.0;
}

int main() {
    const int span = 9;
    Ewma fair(2.0 / (span + 1));  // alpha 0.2
    double mid;
    std::cout << std::fixed << std::setprecision(2);
    while (std::cin >> mid) {
        // Score the new mid against the past, then let it in.
        if (fair.count() < 5) {
            std::cout << mid << "  warming up\n";
        } else {
            double z = zscore(mid, fair.mean(), fair.stdev());
            const char* signal = z > 2.0 ? "SELL" : z < -2.0 ? "BUY" : "-";
            std::cout << mid << "  ewma " << fair.mean() << "  sd " << fair.stdev() << "  z " << z << "  " << signal << '\n';
        }
        fair.add(mid);
    }
    return 0;
}

