steps.body:
Two instruments rarely move alone. A stock rises with its index and two banks fall together, and every hedge or pairs trade depends on how tightly. The online version is Welford for two variables: both means, both `m2` sums, and a co-moment `c_xy_`, the sum of the products of the two distances from their means:

```cpp harness
#include <iostream>

long n_ = 0;
double mean_x_ = 0.0, mean_y_ = 0.0, c_xy_ = 0.0;

int main() {
    double xs[] = {1.0, 2.0, 3.0};
    double ys[] = {2.0, 4.0, 7.0};
    for (int i = 0; i < 3; ++i) {
        double x = xs[i], y = ys[i];
        ++n_;
        {{code}}
    }
    std::cout << c_xy_ / (n_ - 1) << '\n';
    return 0;
}
```

```cpp
double dx = x - mean_x_;      // before the mean moves
mean_x_ += dx / n_;
double dy = y - mean_y_;
mean_y_ += dy / n_;
c_xy_ += dx * (y - mean_y_);  // old x distance times new y distance
```

From these three sums:

- The covariance is `c_xy_ / (n_ - 1)`.
- The **correlation** is `c_xy_ / std::sqrt(m2_x_ * m2_y_)`, between -1 and 1, whatever the units of either series.
- The **beta** of y on x is `c_xy_ / m2_x_`, the slope of the best straight line through the points. A stock's beta to its index is its hedge ratio: short beta dollars of the index per dollar of stock, and what's left is the stock's own move.

Feed it returns, not prices. Two prices that both trend upward correlate strongly even when their daily moves have nothing to do with each other.

example.code:
#include <cmath>
#include <iomanip>
#include <iostream>

class OnlineCovariance {
public:
    void add(double x, double y) {
        ++n_;
        double dx = x - mean_x_;  // x's distance from its old mean
        mean_x_ += dx / n_;
        double dy = y - mean_y_;
        mean_y_ += dy / n_;
        m2_x_ += dx * (x - mean_x_);
        m2_y_ += dy * (y - mean_y_);
        c_xy_ += dx * (y - mean_y_);  // old x distance times new y distance
    }
    long count() const { return n_; }
    double covariance() const { return n_ > 1 ? c_xy_ / (n_ - 1) : 0.0; }
    double correlation() const {
        double denom = std::sqrt(m2_x_ * m2_y_);
        return denom > 0.0 ? c_xy_ / denom : 0.0;
    }
    double beta() const { return m2_x_ > 0.0 ? c_xy_ / m2_x_ : 0.0; }  // the slope of y on x

private:
    long n_ = 0;
    double mean_x_ = 0.0, mean_y_ = 0.0;
    double m2_x_ = 0.0, m2_y_ = 0.0, c_xy_ = 0.0;
};

int main() {
    OnlineCovariance stock_vs_index;  // x: the index, y: the stock
    double prev_index, prev_stock, index, stock;
    std::cin >> prev_index >> prev_stock;
    while (std::cin >> index >> stock) {
        double index_bp = (index - prev_index) / prev_index * 10000.0;
        double stock_bp = (stock - prev_stock) / prev_stock * 10000.0;
        stock_vs_index.add(index_bp, stock_bp);
        prev_index = index;
        prev_stock = stock;
    }
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "returns:     " << stock_vs_index.count() << '\n';
    std::cout << "covariance:  " << stock_vs_index.covariance() << " bp^2\n";
    std::cout << "correlation: " << stock_vs_index.correlation() << '\n';
    std::cout << "beta:        " << stock_vs_index.beta() << '\n';
    return 0;
}

