    double covariance() const { return n_ > 1 ? c_xy_ / (n_ - 1) : 0.0; }
    double correlation() const {
        double denom = std::sqrt(m2_x_ * m2_y_);
        return denom > 0.0 ? c_xy_ / denom : 0.0;
    }

private:
    long n_ = 0;
    double mean_x_ = 0.0, mean_y_ = 0.0;
    double m2_x_ = 0.0, m2_y_ = 0.0, c_xy_ = 0.0;
};

int main() {
    OnlineCovariance banks;  // x: the first bank, y: the second
    double prev_a, prev_b, a, b;
    std::cin >> prev_a >> prev_b;
    while (std::cin >> a >> b) {
        banks.add((a - prev_a) / prev_a * 10000.0, (b - prev_b) / prev_b * 10000.0);
        prev_a = a;
        prev_b = b;
    }
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "returns: " << banks.count() << '\n';
    std::cout << "covariance: " << banks.covariance() << '\n';
    std::cout << "correlation: " << banks.correlation() << '\n';
    return 0;
}
